using System;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;
using Rhino;
using Rhino.Geometry;
using Rhino.Geometry.Intersect;
namespace PlugInSolar {
public static class PvSkyExposureEngine {
 public static PvExposureResult Calculate(PvLayoutBundle b,PvSolarConditions c,double gridM,double offsetM=.001){
  c.Validate();PvSeries.Check(gridM,"Analysis Grid Size",.01,10);PvSeries.Check(offsetM,"Sensor Offset",0,1);if(b?.Layout==null||b.Layout.Panels.Count==0)throw new ArgumentException("Candidate Layout is empty.");int n=b.Layout.Panels.Count,t=c.Hoys.Length,p=c.Vectors.Length;
  if(b.Layout.Frames.Count!=n||b.Layout.Faces.Count!=n||b.Layout.Ids.Count!=n)throw new ArgumentException("Layout IDs/frames/faces are misaligned.");double scale=RhinoMath.UnitScale(UnitSystem.Meters,b.Units),eps=Math.Max(b.Tolerance*10,offsetM*scale);double angle=c.North*Math.PI/180;
  var dirs=c.Vectors.Select(v=>new Vector3d(v[0]*Math.Cos(angle)+v[1]*Math.Sin(angle),v[1]*Math.Cos(angle)-v[0]*Math.Sin(angle),v[2])).ToArray();
  var skySum=new double[t];for(int j=0;j<t;j++)for(int k=0;k<p;k++)skySum[j]+=c.DirectW[k][j]+c.DiffuseW[k][j];var ground=skySum.Select(x=>x/p*c.Albedo).ToArray();
  var skyH=Enumerable.Range(0,p).Select(k=>(c.DirectW[k].Sum()+c.DiffuseW[k].Sum())*c.StepHours/1000).ToArray();double groundH=ground.Sum()*c.StepHours/1000;
  var r=new PvExposureResult{Ids=b.Layout.Ids.ToArray(),Timestamps=c.Timestamps.ToArray(),Hoys=c.Hoys.ToArray(),StepHours=c.StepHours,AreaM2=new double[n],TiltDeg=new double[n],AzimuthDeg=new double[n],Poa=new double[n][],ReferencePoa=new double[n][],BeamVisibility=new double[n][],SkyVisibility=new double[n],GroundVisibility=new double[n],Irradiation=new double[n],ShadingReductionPct=new double[n],CellIrradiation=new double[n][],CellVertices=new double[n][][],CellAreas=new double[n][]};
  using(var mesh=new Mesh()){
   foreach(var brep in b.Context.Concat(b.Layout.Panels)){if(brep==null||!brep.IsValid)throw new ArgumentException("Invalid Additional Shading Geometry or layout geometry.");var parts=Mesh.CreateFromBrep(brep,MeshingParameters.Default);if(parts==null||parts.Length==0)throw new ArgumentException("Could not mesh shading geometry.");foreach(var m in parts){mesh.Append(m);m.Dispose();}}mesh.Compact();long rays=0;
   bool Visible(Point3d point,Vector3d dir)=>Intersection.MeshRay(mesh,new Ray3d(point,dir))<0;
   for(int i=0;i<n;i++){
    var frame=b.Layout.Frames[i];var normal=frame.ZAxis;var box=b.Layout.Faces[i].GetBoundingBox(Transform.PlaneToPlane(frame,Plane.WorldXY));double w=box.Max.X-box.Min.X,h=box.Max.Y-box.Min.Y;int nx=(int)Math.Ceiling(w/(gridM*scale)),ny=(int)Math.Ceiling(h/(gridM*scale));int count=nx*ny;if(nx<1||ny<1||count>1600)throw new ArgumentException("More than 1600 analysis cells per panel; increase Analysis Grid Size.");rays+=(long)count*p*2;if(rays>80000000)throw new ArgumentException("More than 80 million visibility rays; increase grid size or use Standard sky.");
    r.CellIrradiation[i]=new double[count];r.CellVertices[i]=new double[count][];r.CellAreas[i]=Enumerable.Repeat(w*h/(scale*scale*count),count).ToArray();r.AreaM2[i]=w*h/(scale*scale);r.TiltDeg[i]=Math.Acos(Math.Max(-1,Math.Min(1,normal.Z)))*180/Math.PI;r.AzimuthDeg[i]=(Math.Atan2(normal.X,normal.Y)*180/Math.PI-c.North+720)%360;
    var weights=new double[p];var groundWeights=new double[p];var refWeights=dirs.Select(d=>Math.Max(0,normal*d)).ToArray();var refGroundWeights=dirs.Select(d=>Math.Max(0,normal*(-d))).ToArray();
    int index=0;for(int x=0;x<nx;x++)for(int y=0;y<ny;y++,index++){
     double x0=box.Min.X+x*w/nx,x1=box.Min.X+(x+1)*w/nx,y0=box.Min.Y+y*h/ny,y1=box.Min.Y+(y+1)*h/ny;var corners=new[]{frame.PointAt(x0,y0),frame.PointAt(x1,y0),frame.PointAt(x1,y1),frame.PointAt(x0,y1)};r.CellVertices[i][index]=corners.SelectMany(q=>new[]{q.X,q.Y,q.Z}).ToArray();var point=frame.PointAt((x0+x1)/2,(y0+y1)/2)+normal*eps;double energy=0;
     for(int k=0;k<p;k++){double a=refWeights[k]>0&&Visible(point,dirs[k])?refWeights[k]:0;double g=refGroundWeights[k]>0&&Visible(point,-dirs[k])?refGroundWeights[k]:0;weights[k]+=a/count;groundWeights[k]+=g/count;energy+=a*skyH[k]+g*groundH;}r.CellIrradiation[i][index]=energy;
    }
    r.Poa[i]=new double[t];r.ReferencePoa[i]=new double[t];r.BeamVisibility[i]=new double[t];double groundWeight=groundWeights.Sum(),refGroundWeight=refGroundWeights.Sum();
    for(int j=0;j<t;j++){double actual=ground[j]*groundWeight,reference=ground[j]*refGroundWeight,direct=0,directRef=0;for(int k=0;k<p;k++){double v=c.DirectW[k][j]+c.DiffuseW[k][j];actual+=weights[k]*v;reference+=refWeights[k]*v;direct+=weights[k]*c.DirectW[k][j];directRef+=refWeights[k]*c.DirectW[k][j];}r.Poa[i][j]=actual;r.ReferencePoa[i][j]=reference;r.BeamVisibility[i][j]=directRef>0?Math.Min(1,direct/directRef):1;}
    r.Irradiation[i]=r.Poa[i].Sum()*c.StepHours/1000;double referenceH=r.ReferencePoa[i].Sum()*c.StepHours/1000;r.ShadingReductionPct[i]=referenceH>0?Math.Max(0,Math.Min(100,100*(1-r.Irradiation[i]/referenceH))):0;r.SkyVisibility[i]=refWeights.Sum()>0?weights.Sum()/refWeights.Sum():1;r.GroundVisibility[i]=refGroundWeight>0?groundWeight/refGroundWeight:1;
   }
  }
  r.Report=$"{n} panels; {r.CellIrradiation.Sum(x=>x.Length)} grid cells; {t} hourly intervals; {p} sky patches. Time-resolved Perez sky from PV Solar Conditions. Cell irradiation retained for separate visualization; panel POA is the area-average for Electricity. Additional Shading Geometry behavior unchanged; no tree/transmission model added. Reference removes all shading geometry and keeps orientation/weather. Ground uses the Ladybug Incident Radiation hemisphere approximation. No interreflection or electrical mismatch model. Sensor offset {eps/scale:0.######} m. Coordinates use layout document units. Native hourly intervals; HOY/time metadata stored inside Results only.";r.Validate();return r;
 }
}
public sealed class PvSolarExposureV2Component:GH_Component {
    // Legacy component: retained for saved definitions, hidden from new workflows.
    public override GH_Exposure Exposure => GH_Exposure.hidden;

 public PvSolarExposureV2Component():base("PV Solar Exposure","PV Exposure","Evaluate a Candidate Layout against prepared Solar Conditions. Retains grid-cell irradiation for a separate PV Exposure Map and panel-average hourly POA for PV Electricity. Required inputs: Candidate Layout and Solar Conditions.","Pika","02 Performance"){}
 public override Guid ComponentGuid=>new Guid("484eb7cd-e4e4-44a1-91ba-97a114b12402");protected override Bitmap Icon=>Assets.Icon("irradiance");
 protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Candidate Layout","Layout","PV Candidate Layout → Layout. Panel solids, front frames, IDs and existing shading geometry.",GH_ParamAccess.item);p.AddGenericParameter("Solar Conditions","Conditions","PV Solar Conditions → Conditions. Contains hourly sky radiation, sun positions and aligned time metadata.",GH_ParamAccess.item);int k=p.AddBrepParameter("Additional Shading Geometry","Context","Optional extra shading Breps, added to context already in the layout. Current geometric blocking behavior is unchanged; no tree model is added.",GH_ParamAccess.list);p[k].Optional=true;p.AddNumberParameter("Analysis Grid Size","Grid","Maximum calculation cell size on panel fronts, meters, independent of Rhino units. Same cells are used by PV Exposure Map.",GH_ParamAccess.item,.1);p.AddNumberParameter("Sensor Offset","Offset","Distance to evaluate in front of panel fronts, meters. Default 0.001; match this explicitly when comparing Ladybug.",GH_ParamAccess.item,.001);p.AddBooleanParameter("Run","Run","True evaluates geometry against Conditions. False clears results; upstream changes recalculate while true.",GH_ParamAccess.item,false);}
 protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddGenericParameter("Solar Exposure Results","Results","Grouped panel-average hourly POA, panel/cell irradiation, cell vertices/areas, IDs, reference and reduction metrics, hidden HOYs/calendar/interval metadata and settings. Connect to PV Electricity and PV Exposure Map.",GH_ParamAccess.item);p.AddNumberParameter("Panel Irradiance","POA","W/m², branch {panel index}, values follow Conditions weather record order. Area-average across panel grid cells; time metadata remains inside Results.",GH_ParamAccess.tree);p.AddNumberParameter("Panel Irradiation","H","kWh/m² accumulated over supplied hours, spatially averaged per panel.",GH_ParamAccess.list);p.AddNumberParameter("Panel Incident Solar Energy","Solar kWh","Incident sunlight kWh per panel = panel irradiation × analysis area. This is not generated electricity.",GH_ParamAccess.list);p.AddNumberParameter("Total Incident Solar Energy","Total kWh","Sum of incident sunlight on all panels, kWh, not electricity.",GH_ParamAccess.item);p.AddNumberParameter("Irradiation Reduction","Shade%","Per-panel percent reduction against same orientation/weather with all obstruction removed. Not electrical mismatch loss.",GH_ParamAccess.list);p.AddTextParameter("Panel IDs","IDs","Panel identity matching POA branches and summary results.",GH_ParamAccess.list);p.AddTextParameter("Report","Report","Calculation/model assumptions and diagnostics. Visualization is handled separately.",GH_ParamAccess.item);}
 protected override void SolveInstance(IGH_DataAccess da){try{bool run=false;da.GetData(5,ref run);if(!run){Message="Set Run = True";return;}IGH_Goo layout=null,conditions=null;double grid=.1,offset=.001;if(!da.GetData(0,ref layout)||!da.GetData(1,ref conditions)||!da.GetData(3,ref grid)||!da.GetData(4,ref offset))return;var b=PvPanelCatalog.Unwrap<PvCandidateLayoutData>(layout).Value;var c=PvPanelCatalog.Unwrap<PvSolarConditionsData>(conditions).Data;var extra=new List<Brep>();da.GetDataList(2,extra);var r=PvSkyExposureEngine.Calculate(new PvLayoutBundle{Layout=b.Layout,Units=b.Units,Tolerance=b.Tolerance,Context=b.Context.Concat(extra).ToList()},c,grid,offset);var energy=r.Irradiation.Select((x,i)=>x*r.AreaM2[i]).ToArray();da.SetData(0,new PvExposureData(r));da.SetDataTree(1,PvDataTrees.Numbers(r.Poa));da.SetDataList(2,r.Irradiation);da.SetDataList(3,energy);da.SetData(4,energy.Sum());da.SetDataList(5,r.ShadingReductionPct);da.SetDataList(6,r.Ids);da.SetData(7,r.Report);Message=$"{r.Ids.Length} panels evaluated";}catch(Exception e){foreach(var p in Params.Output)p.ClearData();Message="";AddRuntimeMessage(GH_RuntimeMessageLevel.Error,e.Message);}}
}
}
